                Ok(_) => println!("checkout ok"),
                Err(e) => println!("checkout ERR: {}", e),
            }
        },
        "add" => {
            let path = args.get(2).unwrap();
            let repo = Repository::open(path).unwrap();
            let mut index = repo.index().unwrap();
            // Try add with absolute vs relative?
