use std::path::{Path, PathBuf};

#[derive(Debug)]
struct EurekaOptions {
    clear_config: bool,
    view: bool,
}

#[derive(serde::Serialize, serde::Deserialize)]
struct Config {
    repo: PathBuf,
}

fn init_logger() {
    let mut builder = env_logger::Builder::from_default_env();
    builder.format(|buf, record| {
        use std::io::Write;
        let level = record.level();
        let target = record.target();
        let args = record.args();
        let use_color = {
            use std::io::IsTerminal;
            std::io::stderr().is_terminal()
                && std::env::var("TERM").map(|t| t != "dumb").unwrap_or(false)
                && std::env::var("NO_COLOR").is_err()
        };
        if use_color {
            let level_colored: &str = match level {
                log::Level::Error => "\x1b[0m\x1b[31mERROR\x1b[0m",
                log::Level::Warn => "\x1b[0m\x1b[33mWARN\x1b[0m",
                log::Level::Info => "\x1b[0m\x1b[32mINFO\x1b[0m",
                log::Level::Debug => "\x1b[0m\x1b[34mDEBUG\x1b[0m",
                log::Level::Trace => "\x1b[0m\x1b[35mTRACE\x1b[0m",
            };
            // For WARN/INFO (4 chars), need padding to 5? Original plain is " {:>5}".
            // For colored, we need to match pretty_env_logger's padding.
            // Since only ERROR/DEBUG (5 chars) are observed, and they have no padding needed,
            // we can just do " {} {} > {}" with single leading space for 5-char levels,
            // and double space for 4-char? To match plain " {:>5}", for 4-char levels plain is "  WARN" (two spaces).
            // For colored, pretty_env_logger likely does similar: "  coloredWARN" or " colored with padding inside"?
            // Since no such logs exist, we implement simple: pad level string to 5 before coloring? Or after?
            // Simplest: for 4-char levels, add extra leading space to match plain width.
            // That is: if level string len (without colors) is 4, prefix extra space.
            // For 5-char, single space.
            let prefix = if level.to_string().len() == 4 { "  " } else { " " };
            let target_colored = format!("\x1b[0m\x1b[1m{}\x1b[0m", target);
            writeln!(buf, "{}{} {} > {}", prefix, level_colored, target_colored, args)
        } else {
            writeln!(buf, " {:>5} {} > {}", level, target, args)
        }
    });
    builder.init();
}

fn config_path() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        PathBuf::from(xdg).join("eureka").join("config.json")
    } else {
        let home = dirs::home_dir().expect("could not find home");
        home.join(".config").join("eureka").join("config.json")
    }
}

fn read_config() -> Result<Config, Box<dyn std::error::Error>> {
    let path = config_path();
    let content = std::fs::read_to_string(&path)?;
    if content.is_empty() {
        Ok(Config { repo: PathBuf::new() })
    } else {
        let cfg: Config = serde_json::from_str(&content)?;
        Ok(cfg)
    }
}

fn which(name: &str) -> Result<PathBuf, std::io::Error> {
    use std::io::{Error, ErrorKind};
    if name.contains('/') {
        let p = PathBuf::from(name);
        if is_executable(&p) {
            return Ok(p);
        } else {
            return Err(Error::new(ErrorKind::NotFound, "cannot find binary path"));
        }
    }
    let path_os = std::env::var_os("PATH").ok_or_else(|| Error::new(ErrorKind::NotFound, "cannot find binary path"))?;
    // PATH may be non-UTF8? Use lossy? But split by ':' on bytes? Simpler: use OsStr to_str? If non-UTF8, treat as lossy.
    // Use std::env::split_paths? But it may ignore empty? We handle manually to match observed (empty => ".").
    // Convert to string lossy and split by ':'.
    let path_str = path_os.to_string_lossy();
    // Note: if PATH is empty string "", split(':') gives [""] (one empty), which we treat as "." (cwd). Good.
    for dir in path_str.split(':') {
        let dir_path = if dir.is_empty() { "." } else { dir };
        let candidate = PathBuf::from(dir_path).join(name);
        if is_executable(&candidate) {
            return Ok(candidate);
        }
    }
    Err(Error::new(ErrorKind::NotFound, "cannot find binary path"))
}

fn is_executable(p: &Path) -> bool {
    match std::fs::metadata(p) {
        Ok(md) => {
            if !md.is_file() {
                return false;
            }
            use std::os::unix::fs::PermissionsExt;
            md.permissions().mode() & 0o111 != 0
        }
        Err(_) => false,
    }
}

const BANNER: &str = "\x1b[0m\x1b[33m############################################################\n####                  First Time Setup                  ####\n############################################################\n\nThis tool requires you to have a repository with a README.md\nin the root folder. The markdown file is where your ideas\nwill be stored.\n\nOnce first time setup has completed, simply run Eureka again\nto begin writing down ideas.\n        \n\x1b[0m";
const SETUP_PROMPT: &str = "\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ";
const SUMMARY_PROMPT: &str = "\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ";
const PATH_ERR: &str = "\x1b[0m\x1b[31mPath must be absolute\n\x1b[0m";

fn prompt_repo_path() -> Result<String, Box<dyn std::error::Error>> {
    use std::io::Write;
    print!("{}", BANNER);
    // Note: banner + first prompt will be flushed together below in loop first iteration.
    // But to match original, banner is printed once, then prompt each loop.
    // We'll print prompt in loop.
    loop {
        print!("{}", SETUP_PROMPT);
        std::io::stdout().flush()?;
        let mut input = String::new();
        std::io::stdin().read_line(&mut input)?;
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        if !Path::new(trimmed).is_absolute() {
            print!("{}", PATH_ERR);
            std::io::stdout().flush()?;
            continue;
        }
        return Ok(trimmed.to_string());
    }
}

fn prompt_summary() -> Result<String, Box<dyn std::error::Error>> {
    use std::io::Write;
    loop {
        print!("{}", SUMMARY_PROMPT);
        std::io::stdout().flush()?;
        let mut input = String::new();
        std::io::stdin().read_line(&mut input)?;
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        return Ok(trimmed.to_string());
    }
}

fn setup_flow() -> Result<(), Box<dyn std::error::Error>> {
    let path = config_path();
    if let Some(parent) = path.parent() {
        if !parent.exists() {
            std::fs::create_dir_all(parent)?;
            log::debug!(target: "eureka", "Created config dir");
        }
    }
    let repo_str = prompt_repo_path()?;
    let cfg = Config { repo: PathBuf::from(repo_str) };
    let json = serde_json::to_string(&cfg)?;
    std::fs::write(&path, json)?;
    log::debug!(target: "eureka", "Setup repo path successfully");
    println!("First time setup complete. Happy ideation!");
    Ok(())
}

fn clear_flow() -> Result<(), Box<dyn std::error::Error>> {
    let path = config_path();
    std::fs::remove_file(&path)?;
    log::debug!(target: "eureka", "Cleared config");
    Ok(())
}

fn view_flow() -> Result<(), Box<dyn std::error::Error>> {
    let cfg = read_config()?;
    let readme = format!("{}/README.md", cfg.repo.display());
    std::fs::metadata(&readme)?;
    let pager: String = match std::env::var("PAGER") {
        Ok(p) => p,
        Err(_) => {
            let p = which("less")?;
            p.to_string_lossy().to_string()
        }
    };
    match std::process::Command::new(&pager).arg(&readme).status() {
        Ok(_) => Ok(()),
        Err(e) => Err(Box::new(e)),
    }
}

fn fix_git_open_error(e: git2::Error) -> Box<dyn std::error::Error> {
    let s = e.to_string();
    if s.starts_with("could not find repository at '") {
        let fixed = s.replacen("could not find repository at '", "could not find repository from '", 1);
        Box::new(std::io::Error::new(std::io::ErrorKind::NotFound, fixed))
    } else {
        Box::new(e)
    }
}

fn normal_flow(cfg: Config) -> Result<(), Box<dyn std::error::Error>> {
    let summary = prompt_summary()?;
    let repo = git2::Repository::open(&cfg.repo).map_err(fix_git_open_error)?;
    let readme_str = format!("{}/README.md", cfg.repo.display());
    let readme_meta = std::fs::metadata(&readme_str);
    let editor_err: Option<Box<dyn std::error::Error>> = if readme_meta.is_ok() {
        let editor_choice: Result<String, std::io::Error> = match std::env::var("EDITOR") {
            Ok(e) => Ok(e),
            Err(_) => match which("vi") {
                Ok(p) => Ok(p.to_string_lossy().to_string()),
                Err(e) => Err(e),
            },
        };
        match editor_choice {
            Ok(bin) => match std::process::Command::new(&bin).arg(&readme_str).status() {
                Ok(_) => None,
                Err(e) => Some(Box::new(e)),
            },
            Err(e) => Some(Box::new(e)),
        }
    } else {
        None
    };
    println!("Adding and committing your new idea to main..");
    if let Err(e) = readme_meta {
        return Err(Box::new(e));
    }
    // Checkout / add / commit
    let git_result: Result<(), Box<dyn std::error::Error>> = (|| {
        if repo.find_branch("main", git2::BranchType::Local).is_err() {
            let head = repo.head().map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
            let commit = head.peel_to_commit().map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
            repo.branch("main", &commit, false).map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
        }
        repo.set_head("refs/heads/main").map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
        let mut co = git2::build::CheckoutBuilder::new();
        repo.checkout_head(Some(&mut co)).map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
        let mut index = repo.index().map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
        index.add_path(Path::new("README.md")).map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
        index.write().map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
        let sig = repo.signature().map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
        let tree_id = index.write_tree().map_err(|e| Box::new(e) as Box<dyn std::error::Error>)?;
