import pty, os, subprocess, tempfile, time, select

def run_pty(bin_path, args, input_data=None, extra_env={}, timeout=3):
    master, slave = pty.openpty()
    e=dict(os.environ)
    tmp_home=tempfile.mkdtemp()
    e["HOME"]=tmp_home
    for k,v in extra_env.items():
        if v is None:
            e.pop(k, None)
        else:
            e[k]=v
    if "TERM" not in e:
        e["TERM"]="xterm"
    p=subprocess.Popen([bin_path]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=e, text=False, close_fds=True)
    import os as _os
    _os.close(slave)
    if input_data is not None:
        if isinstance(input_data, str):
            input_data=input_data.encode()
        try:
            p.stdin.write(input_data)
            p.stdin.flush()
        except: pass
    try:
        p.stdin.close()
    except: pass
    output=b""
    start=time.time()
    while time.time()-start < timeout:
        r,_,_=select.select([master], [], [], 0.5)
        if r:
            try:
                data=_os.read(master, 4096)
                if not data: break
                output+=data
            except OSError: break
        if p.poll() is not None:
            time.sleep(0.3)
            while True:
                r,_,_=select.select([master], [], [], 0.2)
                if not r: break
                try:
                    data=_os.read(master, 4096)
                    if not data: break
                    output+=data
                except OSError: break
            break
    try: p.terminate()
    except: pass
    try: p.wait(timeout=1)
    except:
        try: p.kill()
        except: pass
    _os.close(master)
    return p.returncode, output

def compare_pty(name, args, input_data, extra_env):
    print(f"=== PTY {name} ===")
    c1, o1 = run_pty("/workspace/executable", args, input_data, extra_env)
    c2, o2 = run_pty("/workspace/target/debug/executable", args, input_data, extra_env)
    if c1!=c2:
        print(f"FAIL exit {c1} vs {c2}")
        return False
    if o1!=o2:
        print(f"FAIL output mismatch len {len(o1)} vs {len(o2)}")
        # Find diff
        l=min(len(o1), len(o2))
        for i in range(l):
            if o1[i]!=o2[i]:
                print(f" diff at {i}: orig={repr(o1[max(0,i-100):i+200])} new={repr(o2[max(0,i-100):i+200])}")
                break
        if len(o1)!=len(o2):
            print(f" orig tail: {repr(o1[-500:])}")
            print(f" new tail: {repr(o2[-500:])}")
        return False
    print("PASS")
    return True

